`),s("span",{class:"line"}),n(`
`),s("span",{class:"line"},[n("    union "),s("span",{class:"token operator"},"="),n(" pred_area"),s("span",{class:"token punctuation"},"["),s("span",{class:"token punctuation"},":"),s("span",{class:"token punctuation"},","),n(),s("span",{class:"token boolean"},"None"),s("span",{class:"token punctuation"},"]"),n(),s("span",{class:"token operator"},"+"),n(" target_area"),s("span",{class:"token punctuation"},"["),s("span",{class:"token boolean"},"None"),s("span",{class:"token punctuation"},","),n(),s("span",{class:"token punctuation"},":"),s("span",{class:"token punctuation"},"]"),n(),s("span",{class:"token operator"},"-"),n(" intersection")]),n(`
